document.querySelectorAll('[data-filter-table]').forEach(t=>{const amount=document.querySelector('[data-amount-filter]');const method=document.querySelector('[data-method-filter]');function go(){for(const row of t.tBodies[0].rows){row.hidden=(amount&&amount.value!=='all'&&row.dataset.amount!==amount.value)||(method&&method.value!=='all'&&row.dataset.method!==method.value)}}amount?.addEventListener('change',go);method?.addEventListener('change',go)});